/** WeAreDevs-style outer shell for offline loadstrings */
export function wrapWeAreDevs(innerLoader: string, id: string): string {
  let body = innerLoader;
  const safe = body.replace(/\]=+\]/g, (m) => m[0] + "\\" + m.slice(1));
  const seed = Array.from(id).reduce((a, c) => (a * 33 + c.charCodeAt(0)) >>> 0, 0x517cc1);
  const v1 = "_W" + (seed % 9999);
  const v2 = "_R" + ((seed >> 8) % 9999);
  const v3 = "_D" + ((seed >> 16) % 9999);
  return `-- WeAreDevs.com
-- This script was generated by WeAreDevs Obfuscator
-- https://wearedevs.net

local ${v1} = [==========[${safe}]==========]
local ${v2} = loadstring or load
local ${v3}, _err = ${v2}(${v1})
if not ${v3} then
  error("WeAreDevs: " .. tostring(_err), 0)
end
return ${v3}()
`;
}
